import os, json, urllib.parse, urllib.request, sys, time

def get_key():
    for line in open(os.path.expanduser("~/.claude/api_keys.env")):
        if line.startswith("OPENALEX_API_KEY_MANUAL="):
            return line.split("=",1)[1].strip().strip('"').strip("'")
    return ""

KEY = get_key()

def oa(path, params):
    params = dict(params)
    if KEY:
        params["api_key"] = KEY
    url = "https://api.openalex.org/" + path + "?" + urllib.parse.urlencode(params)
    for attempt in range(3):
        try:
            with urllib.request.urlopen(url, timeout=60) as r:
                return json.load(r)
        except Exception as e:
            if attempt == 2:
                raise
            time.sleep(2)

def ta(query, frm="2010-01-01", n=6, sort="relevance_score:desc"):
    d = oa("works", {"filter": f"title_and_abstract.search:{query},from_publication_date:{frm}",
                     "per-page": n, "sort": sort, "select": "doi,title,publication_year,cited_by_count"})
    return d

def show(label, query, frm="2010-01-01", n=6, sort="relevance_score:desc"):
    d = ta(query, frm, n, sort)
    print(f"## {label}  [n={d['meta']['count']}]")
    for r in d.get("results", []):
        print(f"   {r.get('publication_year')} |c{r.get('cited_by_count')} | {(r.get('title') or '')[:118]} | {r.get('doi')}")
    print()

if __name__ == "__main__":
    for line in sys.stdin.read().strip().split("\n"):
        if not line.strip() or line.startswith("#"):
            continue
        label, query = line.split("||", 1)
        show(label.strip(), query.strip())

